16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
20	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
21	import org.springframework.samples.petclinic.rest.validation.TelephoneFormatter;
22	
23	import jakarta.persistence.*;
24	import jakarta.validation.constraints.NotEmpty;
25	import jakarta.validation.constraints.Pattern;
26	
27	import java.time.LocalDate;
28	import java.time.temporal.ChronoUnit;
29	import java.util.*;
30	
31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "membership_number")
86	    private String membershipNumber;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    /**
95	     * Default the registration date to the server's current date when none was
96	     * supplied, then roll the effective date forward onto a business day so a
97	     * weekend registration date always lands on the following Monday. Runs only
98	     * on insert.
99	     */
100	    @PrePersist
101	    private void defaultRegistrationDate() {
102	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
103	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
104	    }
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    public String getAddressLine1() {
115	        return this.addressLine1;
116	    }
117	
118	    public void setAddressLine1(String addressLine1) {
119	        this.addressLine1 = addressLine1;
120	    }
121	
122	    public String getAddressLine2() {
123	        return this.addressLine2;
124	    }
125	
126	    public void setAddressLine2(String addressLine2) {
127	        this.addressLine2 = addressLine2;
128	    }
129	
130	    public String getCity() {
131	        return this.city;
132	    }
133	
134	    public void setCity(String city) {
135	        this.city = city;
136	    }
137	
138	    public String getTelephone() {
139	        return this.telephone;
140	    }
141	
142	    public void setTelephone(String telephone) {
143	        this.telephone = telephone;
144	    }
145	
146	    public String getEmail() {
147	        return this.email;
148	    }
149	
150	    public void setEmail(String email) {
151	        this.email = email;
152	    }
153	
154	    public String getPostcode() {
155	        return this.postcode;
156	    }
157	
158	    public void setPostcode(String postcode) {
159	        this.postcode = postcode;
160	    }
161	
162	    public LocalDate getRegistrationDate() {
163	        return this.registrationDate;
164	    }
165	
166	    public void setRegistrationDate(LocalDate registrationDate) {
167	        this.registrationDate = registrationDate;
168	    }
169	
170	    public LocalDate getBirthDate() {
171	        return this.birthDate;
172	    }
173	
174	    public void setBirthDate(LocalDate birthDate) {
175	        this.birthDate = birthDate;
176	    }
177	
178	    public String getCustomerCode() {
179	        return this.customerCode;
180	    }
181	
182	    public void setCustomerCode(String customerCode) {
183	        this.customerCode = customerCode;
184	    }
185	
186	    public String getHouseholdId() {
187	        return this.householdId;
188	    }
189	
190	    public void setHouseholdId(String householdId) {
191	        this.householdId = householdId;
192	    }
193	
194	    public Integer getNamesakeCount() {
195	        return this.namesakeCount;
196	    }
197	
198	    public void setNamesakeCount(Integer namesakeCount) {
199	        this.namesakeCount = namesakeCount;
200	    }
201	
202	    public Integer getHouseholdSize() {
203	        return this.householdSize;
204	    }
205	
206	    public void setHouseholdSize(Integer householdSize) {
207	        this.householdSize = householdSize;
208	    }
209	
210	    public String getMembershipNumber() {
211	        return this.membershipNumber;
212	    }
213	
214	    public void setMembershipNumber(String membershipNumber) {
215	        this.membershipNumber = membershipNumber;
216	    }
217	
218	    public Integer getPossibleDuplicateOf() {
219	        return this.possibleDuplicateOf;
220	    }
221	
222	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
223	        this.possibleDuplicateOf = possibleDuplicateOf;
224	    }
225	
226	    /**
227	     * Return whether this owner is a possible duplicate: true when it was created while an existing
228	     * owner already shared its last name and postcode under a different telephone, i.e. when a
229	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
230	     */
231	    @Transient
232	    public boolean getPossibleDuplicate() {
233	        return this.possibleDuplicateOf != null;
234	    }
235	
236	    /**
237	     * Return this owner's name formatted as {@code LastName, FirstName}.
238	     */
239	    @Transient
240	    public String getDisplayName() {
241	        return this.getLastName() + ", " + this.getFirstName();
242	    }
243	
244	    /**
245	     * Return this owner's telephone formatted for human display: the country code, a space, then
246	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
247	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
248	     */
249	    @Transient
250	    public String getTelephoneDisplay() {
251	        return TelephoneFormatter.format(this.telephone);
252	    }
253	
254	    /**
255	     * Return this owner's identity key: the derived value formed as
256	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
257	     * contributes an empty segment). Members of the same household share a household id but, having
258	     * different telephones, still have distinct identity keys. The telephone and email are expected
259	     * to already be in their normalized storage form.
260	     */
261	    @Transient
262	    public String getIdentityKey() {
263	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
264	    }
265	
266	    private static String orEmpty(String value) {
267	        return value == null ? "" : value;
268	    }
269	
270	    /**
271	     * Return this owner's locality: the REGION segment of the owner's
272	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
273	     * When no customer code has been assigned yet the region is resolved directly from the
274	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
275	     */
276	    @Transient
277	    public String getLocality() {
278	        if (this.customerCode != null && !this.customerCode.isBlank()) {
279	            return CustomerCodeGenerator.regionOf(this.customerCode);
280	        }
281	        return RegionResolver.regionFor(this.postcode, this.city);
282	    }
283	
284	    /**
285	     * Return this owner's timezone: the IANA name mapped from the owner's
286	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
287	     * region has no known timezone.
288	     */
289	    @Transient
290	    public String getTimezone() {
291	        return RegionTimezones.timezoneOf(getLocality());
292	    }
293	
294	    /**
295	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
296	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
297	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
298	     * for long tenure ({@link #getTenureDays() tenure} of more than 365 days).
299	     */
300	    @Transient
301	    public int getMembershipPoints() {
302	        boolean hasEmail = this.email != null && !this.email.isEmpty();
303	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
304	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
305	        boolean longTenure = getTenureDays() > 365;
306	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
307	    }
308	
309	    /**
310	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
311	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
312	     */
313	    @Transient
314	    public int getMembershipLevel() {
315	        return MembershipPoints.levelFor(getMembershipPoints());
316	    }
317	
318	    /**
319	     * Return this owner's tenure in whole days: the number of days elapsed from the
320	     * {@link #getRegistrationDate() registration date} to today. A newly created owner
321	     * whose registration date is today has zero tenure. Zero when no registration date
322	     * is known.
323	     */
324	    @Transient
325	    public long getTenureDays() {
326	        if (this.registrationDate == null) {
327	            return 0;
328	        }
329	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
330	    }
331	
332	    /**
333	     * Return this owner's check digit: the single Luhn check digit computed over the
334	     * digits of the {@link #getCustomerCode() customer code}.
335	     */
336	    @Transient
337	    public int getCheckDigit() {
338	        return LuhnCheckDigit.of(this.customerCode);
339	    }
340	
341	    /**
342	     * Return this owner's preferred contact channel: {@code EMAIL} when an
343	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
344	     */
345	    @Transient
346	    public String getContactPreference() {
347	        boolean hasEmail = this.email != null && !this.email.isEmpty();
348	        return hasEmail ? "EMAIL" : "PHONE";
349	    }
350	
351	    /**
352	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
353	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
354	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
355	     */
356	    @Transient
357	    public String getAgeBand() {
358	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
359	        return ageBand == null ? null : ageBand.name();
360	    }
361	
362	    protected Set<Pet> getPetsInternal() {
363	        if (this.pets == null) {
364	            this.pets = new HashSet<>();
365	        }
366	        return this.pets;
367	    }
368	
369	    protected void setPetsInternal(Set<Pet> pets) {
370	        this.pets = pets;
371	    }
372	
373	    public List<Pet> getPets() {
374	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
375	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
376	        return Collections.unmodifiableList(sortedPets);
377	    }
378	
379	    public void setPets(List<Pet> pets) {
380	        this.pets = new HashSet<>(pets);
381	    }
382	
383	    public void addPet(Pet pet) {
384	        getPetsInternal().add(pet);
385	        pet.setOwner(this);
386	    }
387	
388	    /**
389	     * Return the Pet with the given name, or null if none found for this Owner.
390	     *
391	     * @param name to test
392	     * @return true if pet name is already in use
393	     */
394	    public Pet getPet(String name) {
395	        return getPet(name, false);
396	    }
397	
398	    /**
399	     * Return the Pet with the given name, or null if none found for this Owner.
400	     *
401	     * @param name to test
402	     * @return true if pet name is already in use
403	     */
404	    public Pet getPet(String name, boolean ignoreNew) {
405	        name = name.toLowerCase();
406	        for (Pet pet : getPetsInternal()) {
407	            if (!ignoreNew || !pet.isNew()) {
408	                String compName = pet.getName();
409	                compName = compName.toLowerCase();
410	                if (compName.equals(name)) {
411	                    return pet;
412	                }
413	            }
414	        }
415	        return null;
416	    }
417	
418	    public Pet getPet(Integer petId) {
419	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
420	    }
421	
422	    @Override
423	    public String toString() {
424	        return new ToStringCreator(this)
425	
426	            .append("id", this.getId())
427	            .append("new", this.isNew())
428	            .append("lastName", this.getLastName())
429	            .append("firstName", this.getFirstName())
430	            .append("address", this.address)
431	            .append("city", this.city)
432	            .append("telephone", this.telephone)
433	            .append("email", this.email)
434	            .toString();
435	    }
436	}
